  { name: "REST APIs", category: "Other" },
  { name: "Git", category: "Other" },
  { name: "GitHub", category: "Other" },
];

export const projects = [
  {
    title: "Smart Campus Operations Hub",
    description:
      "Web platform to manage facility, asset bookings (rooms, labs, equipment) and maintenance operations for a university campus.",
    stack: ["Spring Boot", "PostgreSQL", "MySQL"],
    category: "Full Stack",
    color: "#6EE7B7",
  },
  {
    title: "Smart Hostel Management System",
    description:
      "Full-stack application for university students' hostel booking and management with real-time availability.",
    stack: ["MongoDB", "Express.js", "React.js", "Node.js"],
    category: "Full Stack",
    color: "#93C5FD",
  },
  {
    title: "MediTrack — Personal Health Tracker",
    description:
      "Full-stack MERN application for tracking real-time healthcare of patients, with a dedicated doctor view portal.",
    stack: ["MongoDB", "Express.js", "React.js", "Node.js"],
    category: "Full Stack",
    color: "#F9A8D4",
  },
  {
    title: "WellMe",
    description:
      "Wellness mobile app built with Kotlin for Android, focused on mindfulness and managing daily health routines.",
    stack: ["Kotlin", "Android"],
    category: "Mobile",
    color: "#A5B4FC",
  },
  {
    title: "Staff Management System",
    description:
      "MVC-based staff management system built using Java, JSP, and Servlets with OOP principles and a relational database.",
    stack: ["Java", "JSP", "Servlet", "MVC"],
    category: "Backend",
    color: "#FCD34D",
  },
  {
    title: "Tourism & Travel Management System",
    description:
      "A web-based tourism and travel management system with PHP backend and HTML/CSS frontend for bookings and listings.",
